#!/usr/bin/env bash
# Install flatbuffers 25.2.10 headers (required by autogenerated_flatbuffers/*.h).
# The Ubuntu 22.04 package ships 1.12.1 and fails the static_assert in generated headers.
set -euo pipefail

TAG="v25.2.10"
URL="https://codeload.github.com/google/flatbuffers/tar.gz/refs/tags/${TAG}"

ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
WORK="${ROOT}/build/deps"
TARBALL="${WORK}/flatbuffers-${TAG}.tar.gz"

mkdir -p "${WORK}"
echo "==> downloading flatbuffers ${TAG}"
curl -fL --retry 3 --connect-timeout 15 -C - -o "${TARBALL}" "${URL}"

echo "==> extracting headers to /usr/local/include/flatbuffers"
rm -rf "${WORK}/fb" && mkdir -p "${WORK}/fb"
tar -xzf "${TARBALL}" -C "${WORK}/fb"
SRC="$(find "${WORK}/fb" -maxdepth 2 -type d -name flatbuffers | head -1)"
if [ -z "${SRC}" ]; then
  echo "error: flatbuffers directory not found" >&2
  exit 1
fi

sudo rm -rf /usr/local/include/flatbuffers
sudo cp -r "${SRC}" /usr/local/include/
echo "==> installed $(find /usr/local/include/flatbuffers -name '*.h' | wc -l) headers"